const WAVE = process.argv.includes('--f') ? P1F : process.argv.includes('--e') ? P1E : process.argv.includes('--d') ? P1D : process.argv.includes('--c') ? P1C : process.argv.includes('--b') ? P1B : P1;

function prompt([name, id, scene, , tris, desc]) {
  const s = SCENES[scene];
  return `You are working in the Fantasy Asset Forge repository (the current directory). It turns TypeScript asset files into textured 3D models, renders, and pixel-art sprites.

Task: create the asset \`${name}\` (catalog id \`${id}\`) as \`assets/${name}.ts\`.

Description: ${desc} Stand it on y = 0 (unless the description says otherwise), centred on the Y axis, front toward +Z.

Style anchors. Reference images are in \`reference/\`:
- \`reference/${name}-mock.jpg\`: a concept mockup of this asset. Match its idea and colors, not every detail.
- ${s.text}.
They are style guides, not traces: keep the geometry simple enough to model with primitives.

Palette for this scene: ${s.palette}

Art direction (Chibi Quest): rounded chunky forms, soft bevels everywhere, slightly oversized readable features, a silhouette that reads at 128 px. One body per material (wood, iron, cloth, stone, glass, food) with its own roughness and metalness. Glowing parts are emissive bodies, never bright plain paint. Give every emissive body a dark base color (for example #4a1405 under an orange glow, emissiveIntensity about 1.8): a bright base color takes white studio light and washes the glow out to pale peach.

Instructions:
- Before modeling, read AGENTS.md and the skill at \`.claude/skills/forge-assets/SKILL.md\`, with \`references/props.md\` and \`references/materials-and-color.md\`.
- Units are meters.
- Set the asset \`reference\` field to \`reference/${name}-mock.jpg\`.
- Only create or edit \`assets/${name}.ts\`. Do not change any other file. Work only inside the current directory; never use absolute paths.
- Iterate: \`./forge render ${name} --fast\` writes \`out/${name}/render.png\`; look at it, then run \`./forge inspect ${name} --fast\`.
- Finish with \`./forge all ${name}\` and make sure the build prints no \`warning:\` lines.
- Keep the whole asset under ${tris.toLocaleString('en')} triangles.
- You have about 40 minutes. A finished, clean asset beats an ambitious broken one.
`;
}

mkdirSync(`${here}prompts`, { recursive: true });
for (const scene of Object.keys(SCENES)) {
  const dir = `${here}refs/p1-${scene}`;
  mkdirSync(dir, { recursive: true });
  for (const [from, to] of SCENES[scene].anchors) if (existsSync(repo + from)) copyFileSync(repo + from, `${dir}/${to}`);
}
for (const row of WAVE) writeFileSync(`${here}prompts/${row[0]}.prompt.md`, prompt(row));
console.error(`wrote ${WAVE.length} prompts`);

if (process.argv.includes('--queue')) {
  for (const [name, , scene, model] of WAVE)
    console.log([name, model, `bench/overnight/prompts/${name}.prompt.md`, `bench/overnight/refs/p1-${scene}`, 'bench/runs/ov-p1'].join('\t'));
}

if (process.argv.includes('--mockups')) {
  for (const [name, , scene, , , , mock] of WAVE) {
    const out = `${here}refs/p1-${scene}/${name}-mock.jpg`;
    if (existsSync(out)) continue;
    const p = `Cute chunky stylized 3D game asset for a chibi fantasy RPG: ${mock}. Single object centered, three-quarter view, plain light gray studio background, soft studio lighting, rounded soft bevels, cheerful saturated colors, matte clay toy look, no text, no people.`;
    try {
      execFileSync('mmx', ['image', 'generate', '--prompt', p, '--aspect-ratio', '1:1', '--out', out, '--quiet'], { stdio: 'ignore', timeout: 180000 });
    } catch {}
    console.error(`mockup ${name}: ${existsSync(out) ? 'ok' : 'FAILED'}`);
  }
}
